import React from "react";
import { Col, Row, Container } from "react-bootstrap";

export const Newsletter = () => {
  return (
    <>
      <section className="cta-section">
        <Container>
          <Col lg={12}>
            <div className="modern-cta">
              <Row className="align-items-center">

                <Col lg={7}>
                  <h2 className="cta-heading">
                    Let’s Turn Ideas Into Reality ✨
                  </h2>
                  <p className="cta-description">
                    Passionate about building modern and responsive web experiences.
                    Open to internships, freelance collaborations, and full-time opportunities.
                    Let’s connect and create something impactful together.
                  </p>
                </Col>

                <Col lg={5} className="text-lg-end text-center mt-4 mt-lg-0">
                  <a href="#connect" className="cta-button">
                    <span>Let’s Connect</span>
                  </a>
                </Col>

              </Row>
            </div>
          </Col>
        </Container>
      </section>

      {/* Internal Styling */}
      <style>{`
        .cta-section {
          padding: 90px 0;
          background: linear-gradient(135deg, #0f2027, #203a43, #2c5364);
        }

        .modern-cta {
          background: rgba(255, 255, 255, 0.08);
          padding: 55px;
          border-radius: 25px;
          backdrop-filter: blur(15px);
          box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4);
          transition: all 0.4s ease-in-out;
        }

        .modern-cta:hover {
          transform: translateY(-12px);
          box-shadow: 0 30px 60px rgba(0, 0, 0, 0.6);
        }

        .cta-heading {
          font-size: 36px;
          font-weight: 700;
          color: #ffffff;
          letter-spacing: 1px;
          margin-bottom: 20px;
        }

        .cta-description {
          font-size: 17px;
          color: #dcdcdc;
          line-height: 1.8;
        }

        .cta-button {
          display: inline-block;
          padding: 16px 45px;
          border-radius: 50px;
          font-size: 16px;
          font-weight: 600;
          text-decoration: none;
          color: #ffffff;
          background: linear-gradient(90deg, #00c6ff, #0072ff);
          transition: all 0.4s ease;
          box-shadow: 0 12px 30px rgba(0, 0, 0, 0.3);
        }

        .cta-button:hover {
          background: linear-gradient(90deg, #ff512f, #dd2476);
          transform: scale(1.1);
          box-shadow: 0 20px 40px rgba(0, 0, 0, 0.5);
        }
      `}</style>
    </>
  );
};
